package com.parkgrid.parking;
import com.parkgrid.parking.repo.*; import com.parkgrid.parking.service.ParkingManager; import org.junit.jupiter.api.Test; import static org.mockito.Mockito.*; import static org.junit.jupiter.api.Assertions.*;
class ParkingManagerTest { @Test void reserveReturnsFalseWhenAtomicUpdateAffectsNoRows(){ParkingZoneRepository z=mock(ParkingZoneRepository.class); ParkingSlotRepository s=mock(ParkingSlotRepository.class); when(s.reserveIfAvailable(1L)).thenReturn(0); assertFalse(new ParkingManager(z,s).reserve(1L));} @Test void reserveReturnsTrueWhenAtomicUpdateSucceeds(){ParkingZoneRepository z=mock(ParkingZoneRepository.class); ParkingSlotRepository s=mock(ParkingSlotRepository.class); when(s.reserveIfAvailable(1L)).thenReturn(1); assertTrue(new ParkingManager(z,s).reserve(1L));} }
